exercises.prompt:
Reducers are pure functions — testable with plain Node asserts, no React needed. Implement `todosReducer(state, action)` handling `ADD` (`{ id, text }` — appends `{ id, text, done: false }`), `TOGGLE` (`{ id }` — flips `done`), and `REMOVE` (`{ id }` — drops the todo), plus an unknown-action passthrough that returns state unchanged. Verify purity: the input array and its items must never be mutated.

Example:
```js
let s = [];
s = todosReducer(s, { type: 'ADD', id: 1, text: 'ship it' });
s = todosReducer(s, { type: 'ADD', id: 2, text: 'nap' });
s = todosReducer(s, { type: 'TOGGLE', id: 1 });
s = todosReducer(s, { type: 'REMOVE', id: 2 });
s = todosReducer(s, { type: 'UNKNOWN' });
console.log('final state: ' + JSON.stringify(s));

const input = [{ id: 9, text: 'x', done: false }];
const out = todosReducer(input, { type: 'TOGGLE', id: 9 });
console.log('input unchanged: ' + (input[0].done === false));
console.log('output toggled: ' + (out[0].done === true));
console.log('new array: ' + (out !== input));
```
Expected output:
```
final state: [{"id":1,"text":"ship it","done":true}]
input unchanged: true
output toggled: true
new array: true
```

exercises.solution:
const assert = require('node:assert');

function todosReducer(state, action) {
  switch (action.type) {
    case 'ADD':
      return [...state, { id: action.id, text: action.text, done: false }];
    case 'TOGGLE':
      return state.map((t) => (t.id === action.id ? { ...t, done: !t.done } : t));
    case 'REMOVE':
      return state.filter((t) => t.id !== action.id);
    default:
      return state;
  }
}

let s = [];
s = todosReducer(s, { type: 'ADD', id: 1, text: 'ship it' });
s = todosReducer(s, { type: 'ADD', id: 2, text: 'nap' });
s = todosReducer(s, { type: 'TOGGLE', id: 1 });
s = todosReducer(s, { type: 'REMOVE', id: 2 });
s = todosReducer(s, { type: 'UNKNOWN' });
assert.deepStrictEqual(s, [{ id: 1, text: 'ship it', done: true }]);
console.log('final state: ' + JSON.stringify(s));

const input = [{ id: 9, text: 'x', done: false }];
const out = todosReducer(input, { type: 'TOGGLE', id: 9 });
assert.strictEqual(input[0].done, false);
assert.strictEqual(out[0].done, true);
assert.notStrictEqual(out, input);
console.log('input unchanged: ' + (input[0].done === false));
console.log('output toggled: ' + (out[0].done === true));
console.log('new array: ' + (out !== input));

