exercises.prompt:
Extract the core of a `useForm` custom hook into a pure `formReducer` — the same logic React would run, testable without React. State shape: `{ values, errors, submitted }`. Actions:

- `FIELD_CHANGE { name, value }` — set `values[name]`; also clear `errors[name]` if present (typing dismisses the error).
- `VALIDATE { errors }` — replace the `errors` map wholesale.
- `SUBMIT` — set `submitted: true` (the reducer just sets the flag).
- `RESET { initialValues }` — return `{ values: initialValues, errors: {}, submitted: false }`.

Example:
```js
let f = { values: { email: '' }, errors: {}, submitted: false };
f = formReducer(f, { type: 'FIELD_CHANGE', name: 'email', value: 'a@b.c' });
f = formReducer(f, { type: 'VALIDATE', errors: { email: 'invalid' } });
console.log('after validate: ' + JSON.stringify(f.errors));
f = formReducer(f, { type: 'FIELD_CHANGE', name: 'email', value: 'a@b.com' });
console.log('error cleared on change: ' + JSON.stringify(f.errors));
f = formReducer(f, { type: 'SUBMIT' });
console.log('submitted: ' + f.submitted + ' | values kept: ' + JSON.stringify(f.values));
f = formReducer(f, { type: 'RESET', initialValues: { email: '' } });
console.log('after reset: ' + JSON.stringify(f));
```
Expected output:
```
after validate: {"email":"invalid"}
error cleared on change: {}
submitted: true | values kept: {"email":"a@b.com"}
after reset: {"values":{"email":""},"errors":{},"submitted":false}
```

exercises.solution:
function formReducer(state, action) {
  switch (action.type) {
    case 'FIELD_CHANGE': {
      const errors = { ...state.errors };
      delete errors[action.name];
      return {
        ...state,
        values: { ...state.values, [action.name]: action.value },
        errors,
      };
    }
    case 'VALIDATE':
      return { ...state, errors: { ...action.errors } };
    case 'SUBMIT':
      return { ...state, submitted: true };
    case 'RESET':
      return { values: { ...action.initialValues }, errors: {}, submitted: false };
    default:
      return state;
  }
}

let f = { values: { email: '' }, errors: {}, submitted: false };
f = formReducer(f, { type: 'FIELD_CHANGE', name: 'email', value: 'a@b.c' });
f = formReducer(f, { type: 'VALIDATE', errors: { email: 'invalid' } });
console.log('after validate: ' + JSON.stringify(f.errors));
f = formReducer(f, { type: 'FIELD_CHANGE', name: 'email', value: 'a@b.com' });
console.log('error cleared on change: ' + JSON.stringify(f.errors));
