const assert = require('node:assert');

function decideDeps(scenarioId) {
  switch (scenarioId) {
    case 1:
      // Effect syncs with the network keyed on id: id is reactive, declare it.
      return { inEffect: true, deps: ['id'] };
    case 2:
      // roomId is a prop AND formatMessage is re-created every render —
      // both are reactive values used inside the effect. Omitting
      // formatMessage is the stale-closure trap; in real code you'd
      // stabilize it with useCallback or move it inside the effect.
      return { inEffect: true, deps: ['roomId', 'formatMessage'] };
    case 3:
      // Derived data is computed during render — no effect, no deps, no sync.
      return { inEffect: false, deps: [] };
    default:
      throw new Error('unknown scenario: ' + scenarioId);
  }
}

function checkScenario(id, answer) {
  const expected = {
    1: { inEffect: true, deps: ['id'] },
    2: { inEffect: true, deps: ['roomId', 'formatMessage'] },
    3: { inEffect: false, deps: [] },
  }[id];
  try {
    assert.deepStrictEqual(answer, expected);
    return true;
  } catch {
    return false;
  }
}

console.log('scenario 1 (refetch on id):', checkScenario(1, decideDeps(1)) ? 'PASS' : 'FAIL');
console.log('scenario 2 (subscribe on roomId + fn):', checkScenario(2, decideDeps(2)) ? 'PASS' : 'FAIL');
console.log('scenario 3 (derived data):', checkScenario(3, decideDeps(3)) ? 'PASS' : 'FAIL');

