exercises.prompt:
Simulate React's render cycle with plain closures to prove the stale-closure trap — and the ref fix.

`createComponent()` holds `state`. Each `render()` captures the CURRENT state value in a closure and returns an `onClick` handler. `setState(v)` updates state and re-renders, but an OLD handler still closes over the OLD value. `createFixedComponent()` instead reads through a ref-like `{ current }` box that is mutated on every `setState` — the `useRef` pattern.

Example:
```js
const comp = createComponent();
const staleHandler = comp.render(); // captures state = 0
comp.setState(1);
comp.setState(2);
comp.setState(3);
console.log('stale handler sees:', staleHandler.onClick());

const fixed = createFixedComponent();
const fixedHandler = fixed.render(); // reads through a ref-like box
fixed.setState(1);
fixed.setState(2);
fixed.setState(3);
console.log('fixed handler sees:', fixedHandler.onClick());
```
Expected output:
```
stale handler sees: 0
fixed handler sees: 3
```

exercises.solution:
function createComponent() {
  let state = 0;
  return {
    render() {
      const captured = state; // closure over THIS render's value — frozen
      return { onClick: () => captured };
    },
    setState(v) { state = v; },
  };
}

function createFixedComponent() {
  let state = 0;
  const ref = { current: 0 }; // the useRef pattern: mutated, never re-created
  return {
    render() {
      return { onClick: () => ref.current }; // reads latest through the box
    },
    setState(v) { state = v; ref.current = v; },
  };
}

const comp = createComponent();
const staleHandler = comp.render(); // captures state = 0
comp.setState(1);
comp.setState(2);
comp.setState(3);
console.log('stale handler sees:', staleHandler.onClick());

const fixed = createFixedComponent();
const fixedHandler = fixed.render(); // reads through a ref-like box
fixed.setState(1);
fixed.setState(2);
fixed.setState(3);
console.log('fixed handler sees:', fixedHandler.onClick());

